(window.__APPSRC=window.__APPSRC||{})["xmvkq4zed--z-sj-prepa-ssrpf-j2-sf3"]="{\n \"app\": \"xmvkq4zed\",\n \"id\": \"z-sj-prepa-ssrpf-j2-sf3\",\n \"titre\": \"Préparation D.E (J) · J2 SSR/PF MAN SF3\",\n \"session\": \"J\",\n \"annee\": 2026,\n \"nq\": 60,\n \"nsuj\": 1,\n \"origines\": [\n  {\n   \"fichier\": \"prepa-de-2026/J2_SSR_PF_MAN_SF3_J2_corrige_explique.pdf\",\n   \"sha256\": \"18a54b7581f49f32832e182be818003dc7927d39e06d86feb463185cacb04aa9\"\n  }\n ],\n \"antennes\": [\n  {\n   \"name\": \"J DE PRÉPARATION AU D.E\",\n   \"slug\": \"j-preparation-de\",\n   \"session\": \"J\",\n   \"annee\": 2026,\n   \"existe\": true,\n   \"sujets\": [\n    {\n     \"name\": \"J SSR / PF · Prépa D.E J2 (MAN SF3)\",\n     \"slug\": \"prepa-ssrpf-j2-sf3\",\n     \"pages\": \"\",\n     \"count\": 60,\n     \"session\": \"J\",\n     \"annee\": 2026,\n     \"matiere\": \"SSR / PF\",\n     \"source\": \"J2_SSR_PF_MAN_SF3_J2_corrige_explique.pdf\",\n     \"questions\": [\n      {\n       \"id\": \"j-preparation-de__prepa-ssrpf-j2-sf3__0\",\n       \"num\": \"1\",\n       \"type\": \"CAS_CLINIQUE\",\n       \"typeLabel\": \"Étude de cas / Cas clinique\",\n       \"partieTitle\": \"Cas clinique\",\n       \"caseTitle\": \"Cas clinique\",\n       \"caseData\": \"Vous recevez Mme BOA Irène, âgée de 19 ans, GII PII, quatre semaines après son accouchement. Elle allaite son bébé et souhaite débuter une contraception injectable. Après un counseling, elle exprime une préférence pour le Depo-Provera. Vous devez vérifier son éligibilité, lui donner une information adaptée et assurer une prise en charge respectueuse de son choix.\",\n       \"text\": \"Quel est le premier objectif de l'entretien de counseling ?\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"Éviter de discuter des effets secondaires\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"Imposer immédiatement le Depo-Provera\"\n        },\n        {\n         \"letter\": \"C\",\n         \"text\": \"Comprendre les besoins et préférences de Mme BOA\"\n        },\n        {\n         \"letter\": \"D\",\n         \"text\": \"Obtenir son consentement sans lui donner d'information\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": false,\n       \"answer\": \"C. Comprendre les besoins et préférences de Mme BOA\",\n       \"answerLetters\": [\n        \"C\"\n       ],\n       \"explanation\": \"Le counseling est un entretien conseil centré sur les besoins individuels de chaque cliente : il l'aide à arriver à un choix éclairé et à choisir une méthode qui lui convient. Imposer une méthode, éviter les effets secondaires ou obtenir un consentement sans information vont à l'encontre de ses principes (liberté de choix, consentement éclairé).\\n\\nSource : Cours SR/PF 2023 L2 INFAS, chap. 6 Counseling en PF, p. 21-22\",\n       \"sourceDoc\": \"Prépa D.E — J2 SSR/PF MAN SF3 (corrigé expliqué)\",\n       \"sourceFile\": \"J2_SSR_PF_MAN_SF3_J2_corrige_explique.pdf\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-ssrpf-j2-sf3__1\",\n       \"num\": \"2\",\n       \"type\": \"CAS_CLINIQUE\",\n       \"typeLabel\": \"Étude de cas / Cas clinique\",\n       \"partieTitle\": \"Cas clinique\",\n       \"caseTitle\": \"Cas clinique\",\n       \"caseData\": \"Vous recevez Mme BOA Irène, âgée de 19 ans, GII PII, quatre semaines après son accouchement. Elle allaite son bébé et souhaite débuter une contraception injectable. Après un counseling, elle exprime une préférence pour le Depo-Provera. Vous devez vérifier son éligibilité, lui donner une information adaptée et assurer une prise en charge respectueuse de son choix.\",\n       \"text\": \"Parmi les éléments suivants, lesquels contribuent au choix éclairé d'une méthode ?\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"Sécurité et critères d'éligibilité\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"Toutes les propositions de réponse\"\n        },\n        {\n         \"letter\": \"C\",\n         \"text\": \"Tolérance et effets secondaires possibles\"\n        },\n        {\n         \"letter\": \"D\",\n         \"text\": \"Préférence et possibilité de continuité\"\n        },\n        {\n         \"letter\": \"E\",\n         \"text\": \"Efficacité\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": false,\n       \"answer\": \"B. Toutes les propositions de réponse\",\n       \"answerLetters\": [\n        \"B\"\n       ],\n       \"explanation\": \"Le choix éclairé repose sur les qualités d'une méthode : efficacité, sécurité, tolérance (rareté des effets secondaires), coût, continuité, réversibilité, ainsi que sur les critères médicaux d'éligibilité et la préférence de la cliente. Chaque proposition est juste, d'où « Toutes les propositions de réponse ».\\n\\nSource : Cours SR/PF 2023 L2 INFAS, chap. 3 Généralités sur la contraception (qualités d'une méthode), p. 14 ; chap. 4 Critères médicaux d'éligibilité, p. 16\",\n       \"sourceDoc\": \"Prépa D.E — J2 SSR/PF MAN SF3 (corrigé expliqué)\",\n       \"sourceFile\": \"J2_SSR_PF_MAN_SF3_J2_corrige_explique.pdf\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-ssrpf-j2-sf3__2\",\n       \"num\": \"3\",\n       \"type\": \"CAS_CLINIQUE\",\n       \"typeLabel\": \"Étude de cas / Cas clinique\",\n       \"partieTitle\": \"Cas clinique\",\n       \"caseTitle\": \"Cas clinique\",\n       \"caseData\": \"Vous recevez Mme BOA Irène, âgée de 19 ans, GII PII, quatre semaines après son accouchement. Elle allaite son bébé et souhaite débuter une contraception injectable. Après un counseling, elle exprime une préférence pour le Depo-Provera. Vous devez vérifier son éligibilité, lui donner une information adaptée et assurer une prise en charge respectueuse de son choix.\",\n       \"text\": \"Le Depo-Provera appartient à quelle catégorie de contraceptifs ?\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"Méthode de barrière\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"Contraceptif hormonal combiné oral\"\n        },\n        {\n         \"letter\": \"C\",\n         \"text\": \"Dispositif intra-utérin\"\n        },\n        {\n         \"letter\": \"D\",\n         \"text\": \"Contraceptif hormonal progestatif injectable\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": false,\n       \"answer\": \"D. Contraceptif hormonal progestatif injectable\",\n       \"answerLetters\": [\n        \"D\"\n       ],\n       \"explanation\": \"Le Depo-Provera est un contraceptif injectable progestatif (CIP) : il contient uniquement un progestatif analogue à la progestérone, administré par voie parentérale. Ce n'est ni une méthode de barrière, ni une pilule combinée, ni un DIU.\\n\\nSource : Cours SR/PF 2023 L2 INFAS, chap. 13 Contraceptifs hormonaux progestatifs (CHP), p. 68-69\",\n       \"sourceDoc\": \"Prépa D.E — J2 SSR/PF MAN SF3 (corrigé expliqué)\",\n       \"sourceFile\": \"J2_SSR_PF_MAN_SF3_J2_corrige_explique.pdf\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-ssrpf-j2-sf3__3\",\n       \"num\": \"4\",\n       \"type\": \"CAS_CLINIQUE\",\n       \"typeLabel\": \"Étude de cas / Cas clinique\",\n       \"partieTitle\": \"Cas clinique\",\n       \"caseTitle\": \"Cas clinique\",\n       \"caseData\": \"Vous recevez Mme BOA Irène, âgée de 19 ans, GII PII, quatre semaines après son accouchement. Elle allaite son bébé et souhaite débuter une contraception injectable. Après un counseling, elle exprime une préférence pour le Depo-Provera. Vous devez vérifier son éligibilité, lui donner une information adaptée et assurer une prise en charge respectueuse de son choix.\",\n       \"text\": \"Quelle est la substance active généralement associée au Depo-Provera injectable ?\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"Étonogestrel\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"Éthinylestradiol seul\"\n        },\n        {\n         \"letter\": \"C\",\n         \"text\": \"Lévonorgestrel seul sous forme d'implant\"\n        },\n        {\n         \"letter\": \"D\",\n         \"text\": \"Acétate de médroxyprogestérone retard\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": false,\n       \"answer\": \"D. Acétate de médroxyprogestérone retard\",\n       \"answerLetters\": [\n        \"D\"\n       ],\n       \"explanation\": \"Dans le tableau des injectables progestatifs, la DCI du Depo-Provera est l'acétate de médroxyprogestérone retard (AMPR). L'étonogestrel est l'hormone de l'Implanon NXT, le lévonorgestrel celle de Jadelle ; l'éthinylestradiol est un œstrogène.\\n\\nSource : Cours SR/PF 2023 L2 INFAS, chap. 13 CHP, tableau comparatif des injectables, p. 69\",\n       \"sourceDoc\": \"Prépa D.E — J2 SSR/PF MAN SF3 (corrigé expliqué)\",\n       \"sourceFile\": \"J2_SSR_PF_MAN_SF3_J2_corrige_explique.pdf\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-ssrpf-j2-sf3__4\",\n       \"num\": \"5\",\n       \"type\": \"CAS_CLINIQUE\",\n       \"typeLabel\": \"Étude de cas / Cas clinique\",\n       \"partieTitle\": \"Cas clinique\",\n       \"caseTitle\": \"Cas clinique\",\n       \"caseData\": \"Vous recevez Mme BOA Irène, âgée de 19 ans, GII PII, quatre semaines après son accouchement. Elle allaite son bébé et souhaite débuter une contraception injectable. Après un counseling, elle exprime une préférence pour le Depo-Provera. Vous devez vérifier son éligibilité, lui donner une information adaptée et assurer une prise en charge respectueuse de son choix.\",\n       \"text\": \"Quelle dose correspond classiquement à l'injection intramusculaire de Depo-Provera ?\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"150 mg\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"30 mg\"\n        },\n        {\n         \"letter\": \"C\",\n         \"text\": \"68 mg\"\n        },\n        {\n         \"letter\": \"D\",\n         \"text\": \"200 µg\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": false,\n       \"answer\": \"A. 150 mg\",\n       \"answerLetters\": [\n        \"A\"\n       ],\n       \"explanation\": \"Le Depo-Provera est dosé à 150 mg par dose, en injection intramusculaire (bras ou fesse). 68 mg correspond à l'Implanon NXT et 200 mg au Noristérat (en mg, pas en µg).\\n\\nSource : Cours SR/PF 2023 L2 INFAS, chap. 13 CHP, tableaux comparatifs injectables et implants, p. 69-70\",\n       \"sourceDoc\": \"Prépa D.E — J2 SSR/PF MAN SF3 (corrigé expliqué)\",\n       \"sourceFile\": \"J2_SSR_PF_MAN_SF3_J2_corrige_explique.pdf\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-ssrpf-j2-sf3__5\",\n       \"num\": \"6\",\n       \"type\": \"CAS_CLINIQUE\",\n       \"typeLabel\": \"Étude de cas / Cas clinique\",\n       \"partieTitle\": \"Cas clinique\",\n       \"caseTitle\": \"Cas clinique\",\n       \"caseData\": \"Vous recevez Mme BOA Irène, âgée de 19 ans, GII PII, quatre semaines après son accouchement. Elle allaite son bébé et souhaite débuter une contraception injectable. Après un counseling, elle exprime une préférence pour le Depo-Provera. Vous devez vérifier son éligibilité, lui donner une information adaptée et assurer une prise en charge respectueuse de son choix.\",\n       \"text\": \"Quel intervalle d'administration est habituellement associé au Depo-Provera injectable intramusculaire ?\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"Toutes les quatre semaines\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"Une fois par an\"\n        },\n        {\n         \"letter\": \"C\",\n         \"text\": \"Tous les six mois\"\n        },\n        {\n         \"letter\": \"D\",\n         \"text\": \"Environ 12 à 13 semaines\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": false,\n       \"answer\": \"D. Environ 12 à 13 semaines\",\n       \"answerLetters\": [\n        \"D\"\n       ],\n       \"explanation\": \"La durée d'action du Depo-Provera est de 3 mois : la cliente revient toutes les 12 semaines pour l'injection suivante (Noristérat : toutes les 8 semaines ; injectable combiné : tous les mois).\\n\\nSource : Cours SR/PF 2023 L2 INFAS, chap. 13 CHP, tableau des injectables p. 69 et instructions aux utilisatrices de CIP p. 83\",\n       \"sourceDoc\": \"Prépa D.E — J2 SSR/PF MAN SF3 (corrigé expliqué)\",\n       \"sourceFile\": \"J2_SSR_PF_MAN_SF3_J2_corrige_explique.pdf\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-ssrpf-j2-sf3__6\",\n       \"num\": \"7\",\n       \"type\": \"CAS_CLINIQUE\",\n       \"typeLabel\": \"Étude de cas / Cas clinique\",\n       \"partieTitle\": \"Cas clinique\",\n       \"caseTitle\": \"Cas clinique\",\n       \"caseData\": \"Vous recevez Mme BOA Irène, âgée de 19 ans, GII PII, quatre semaines après son accouchement. Elle allaite son bébé et souhaite débuter une contraception injectable. Après un counseling, elle exprime une préférence pour le Depo-Provera. Vous devez vérifier son éligibilité, lui donner une information adaptée et assurer une prise en charge respectueuse de son choix.\",\n       \"text\": \"Quel élément doit être vérifié avant de décider du démarrage de la méthode ?\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"Les antécédents et la situation clinique pertinents\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"Aucun élément clinique ni contraceptif\"\n        },\n        {\n         \"letter\": \"C\",\n         \"text\": \"Le choix du partenaire à la place de la cliente\"\n        },\n        {\n         \"letter\": \"D\",\n         \"text\": \"Uniquement la couleur des yeux\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": false,\n       \"answer\": \"A. Les antécédents et la situation clinique pertinents\",\n       \"answerLetters\": [\n        \"A\"\n       ],\n       \"explanation\": \"Avant de démarrer une méthode, la consultation en PF recherche les antécédents médicaux, chirurgicaux, gynécologiques et obstétricaux, afin d'identifier les contre-indications et de s'assurer que la cliente n'est pas enceinte. C'est la cliente, et non le partenaire, qui choisit.\\n\\nSource : Cours SR/PF 2023 L2 INFAS, chap. 7 Consultation en PF (buts et interrogatoire), p. 25-26\",\n       \"sourceDoc\": \"Prépa D.E — J2 SSR/PF MAN SF3 (corrigé expliqué)\",\n       \"sourceFile\": \"J2_SSR_PF_MAN_SF3_J2_corrige_explique.pdf\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-ssrpf-j2-sf3__7\",\n       \"num\": \"8\",\n       \"type\": \"CAS_CLINIQUE\",\n       \"typeLabel\": \"Étude de cas / Cas clinique\",\n       \"partieTitle\": \"Cas clinique\",\n       \"caseTitle\": \"Cas clinique\",\n       \"caseData\": \"Vous recevez Mme BOA Irène, âgée de 19 ans, GII PII, quatre semaines après son accouchement. Elle allaite son bébé et souhaite débuter une contraception injectable. Après un counseling, elle exprime une préférence pour le Depo-Provera. Vous devez vérifier son éligibilité, lui donner une information adaptée et assurer une prise en charge respectueuse de son choix.\",\n       \"text\": \"À quatre semaines du post-partum, l'allaitement doit être pris en compte car :\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"Le counseling n'est plus nécessaire\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"Le choix de la méthode dépend notamment du délai post-partum et des critères médicaux\"\n        },\n        {\n         \"letter\": \"C\",\n         \"text\": \"Toutes les méthodes sont automatiquement interdites\"\n        },\n        {\n         \"letter\": \"D\",\n         \"text\": \"L'allaitement rend toute contraception inutile\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": false,\n       \"answer\": \"B. Le choix de la méthode dépend notamment du délai post-partum et des critères médicaux\",\n       \"answerLetters\": [\n        \"B\"\n       ],\n       \"explanation\": \"Le post-partum et l'allaitement font partie des situations classées par les critères médicaux d'éligibilité : le choix de la méthode et le moment de son démarrage en dépendent. L'allaitement ne rend pas la contraception inutile (la MAMA a des conditions strictes) et n'interdit pas toutes les méthodes.\\n\\nSource : Cours SR/PF 2023 L2 INFAS, chap. 4 Critères médicaux d'éligibilité, p. 16 ; chap. 13 CHP, critères d'éligibilité, p. 73 Remarque : le cours classe « allaitement au sein avant 6 semaines du post-partum » en catégorie 3 pour les progestatifs (dont les injectables). Mme BOA, à 4 semaines et allaitante, est donc dans cette situation.\",\n       \"sourceDoc\": \"Prépa D.E — J2 SSR/PF MAN SF3 (corrigé expliqué)\",\n       \"sourceFile\": \"J2_SSR_PF_MAN_SF3_J2_corrige_explique.pdf\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-ssrpf-j2-sf3__8\",\n       \"num\": \"9\",\n       \"type\": \"CAS_CLINIQUE\",\n       \"typeLabel\": \"Étude de cas / Cas clinique\",\n       \"partieTitle\": \"Cas clinique\",\n       \"caseTitle\": \"Cas clinique\",\n       \"caseData\": \"Vous recevez Mme BOA Irène, âgée de 19 ans, GII PII, quatre semaines après son accouchement. Elle allaite son bébé et souhaite débuter une contraception injectable. Après un counseling, elle exprime une préférence pour le Depo-Provera. Vous devez vérifier son éligibilité, lui donner une information adaptée et assurer une prise en charge respectueuse de son choix.\",\n       \"text\": \"La catégorie 1 des critères d'éligibilité médicale signifie :\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"Les risques l'emportent généralement sur les avantages\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"Risques inacceptables pour la santé\"\n        },\n        {\n         \"letter\": \"C\",\n         \"text\": \"Méthode utilisable uniquement en milieu hospitalier\"\n        },\n        {\n         \"letter\": \"D\",\n         \"text\": \"Aucune restriction à l'utilisation de la méthode\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": false,\n       \"answer\": \"D. Aucune restriction à l'utilisation de la méthode\",\n       \"answerLetters\": [\n        \"D\"\n       ],\n       \"explanation\": \"Catégorie 1 = aucune restriction d'utilisation : la méthode peut être utilisée dans n'importe quelles circonstances.\\n\\nSource : Cours SR/PF 2023 L2 INFAS, chap. 4 Critères médicaux d'éligibilité, système de classification, p. 16\",\n       \"sourceDoc\": \"Prépa D.E — J2 SSR/PF MAN SF3 (corrigé expliqué)\",\n       \"sourceFile\": \"J2_SSR_PF_MAN_SF3_J2_corrige_explique.pdf\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-ssrpf-j2-sf3__9\",\n       \"num\": \"10\",\n       \"type\": \"CAS_CLINIQUE\",\n       \"typeLabel\": \"Étude de cas / Cas clinique\",\n       \"partieTitle\": \"Cas clinique\",\n       \"caseTitle\": \"Cas clinique\",\n       \"caseData\": \"Vous recevez Mme BOA Irène, âgée de 19 ans, GII PII, quatre semaines après son accouchement. Elle allaite son bébé et souhaite débuter une contraception injectable. Après un counseling, elle exprime une préférence pour le Depo-Provera. Vous devez vérifier son éligibilité, lui donner une information adaptée et assurer une prise en charge respectueuse de son choix.\",\n       \"text\": \"La catégorie 2 signifie :\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"La méthode est définitive\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"Aucune méthode ne peut être utilisée\"\n        },\n        {\n         \"letter\": \"C\",\n         \"text\": \"Les avantages l'emportent généralement sur les risques\"\n        },\n        {\n         \"letter\": \"D\",\n         \"text\": \"Les risques sont toujours inacceptables\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": false,\n       \"answer\": \"C. Les avantages l'emportent généralement sur les risques\",\n       \"answerLetters\": [\n        \"C\"\n       ],\n       \"explanation\": \"Catégorie 2 = les avantages l'emportent généralement sur les risques : on utilise généralement la méthode.\\n\\nSource : Cours SR/PF 2023 L2 INFAS, chap. 4 Critères médicaux d'éligibilité, p. 16\",\n       \"sourceDoc\": \"Prépa D.E — J2 SSR/PF MAN SF3 (corrigé expliqué)\",\n       \"sourceFile\": \"J2_SSR_PF_MAN_SF3_J2_corrige_explique.pdf\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-ssrpf-j2-sf3__10\",\n       \"num\": \"11\",\n       \"type\": \"CAS_CLINIQUE\",\n       \"typeLabel\": \"Étude de cas / Cas clinique\",\n       \"partieTitle\": \"Cas clinique\",\n       \"caseTitle\": \"Cas clinique\",\n       \"caseData\": \"Vous recevez Mme BOA Irène, âgée de 19 ans, GII PII, quatre semaines après son accouchement. Elle allaite son bébé et souhaite débuter une contraception injectable. Après un counseling, elle exprime une préférence pour le Depo-Provera. Vous devez vérifier son éligibilité, lui donner une information adaptée et assurer une prise en charge respectueuse de son choix.\",\n       \"text\": \"La catégorie 3 signifie généralement :\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"La méthode est obligatoire\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"Aucune restriction d'utilisation\"\n        },\n        {\n         \"letter\": \"C\",\n         \"text\": \"Les risques l'emportent généralement sur les avantages ; une autre méthode est à privilégier si possible\"\n        },\n        {\n         \"letter\": \"D\",\n         \"text\": \"La méthode protège contre toutes les IST\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": false,\n       \"answer\": \"C. Les risques l'emportent généralement sur les avantages ; une autre méthode est à privilégier si possible\",\n       \"answerLetters\": [\n        \"C\"\n       ],\n       \"explanation\": \"Catégorie 3 = les risques l'emportent généralement sur les avantages : l'utilisation n'est généralement pas recommandée, à moins qu'aucune autre méthode ne soit disponible ou acceptable.\\n\\nSource : Cours SR/PF 2023 L2 INFAS, chap. 4 Critères médicaux d'éligibilité, p. 16\",\n       \"sourceDoc\": \"Prépa D.E — J2 SSR/PF MAN SF3 (corrigé expliqué)\",\n       \"sourceFile\": \"J2_SSR_PF_MAN_SF3_J2_corrige_explique.pdf\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-ssrpf-j2-sf3__11\",\n       \"num\": \"12\",\n       \"type\": \"CAS_CLINIQUE\",\n       \"typeLabel\": \"Étude de cas / Cas clinique\",\n       \"partieTitle\": \"Cas clinique\",\n       \"caseTitle\": \"Cas clinique\",\n       \"caseData\": \"Vous recevez Mme BOA Irène, âgée de 19 ans, GII PII, quatre semaines après son accouchement. Elle allaite son bébé et souhaite débuter une contraception injectable. Après un counseling, elle exprime une préférence pour le Depo-Provera. Vous devez vérifier son éligibilité, lui donner une information adaptée et assurer une prise en charge respectueuse de son choix.\",\n       \"text\": \"La catégorie 4 signifie :\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"Risques inacceptables pour la santé ; la méthode ne doit pas être utilisée\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"Aucune restriction d'utilisation\"\n        },\n        {\n         \"letter\": \"C\",\n         \"text\": \"Méthode toujours recommandée\"\n        },\n        {\n         \"letter\": \"D\",\n         \"text\": \"Méthode définitive uniquement\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": false,\n       \"answer\": \"A. Risques inacceptables pour la santé ; la méthode ne doit pas être utilisée\",\n       \"answerLetters\": [\n        \"A\"\n       ],\n       \"explanation\": \"Catégorie 4 = risques inacceptables pour la santé : la méthode ne doit pas être utilisée.\\n\\nSource : Cours SR/PF 2023 L2 INFAS, chap. 4 Critères médicaux d'éligibilité, p. 16\",\n       \"sourceDoc\": \"Prépa D.E — J2 SSR/PF MAN SF3 (corrigé expliqué)\",\n       \"sourceFile\": \"J2_SSR_PF_MAN_SF3_J2_corrige_explique.pdf\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-ssrpf-j2-sf3__12\",\n       \"num\": \"13\",\n       \"type\": \"CAS_CLINIQUE\",\n       \"typeLabel\": \"Étude de cas / Cas clinique\",\n       \"partieTitle\": \"Cas clinique\",\n       \"caseTitle\": \"Cas clinique\",\n       \"caseData\": \"Vous recevez Mme BOA Irène, âgée de 19 ans, GII PII, quatre semaines après son accouchement. Elle allaite son bébé et souhaite débuter une contraception injectable. Après un counseling, elle exprime une préférence pour le Depo-Provera. Vous devez vérifier son éligibilité, lui donner une information adaptée et assurer une prise en charge respectueuse de son choix.\",\n       \"text\": \"Quelles informations sont pertinentes à communiquer à Mme BOA avant l'injection ?\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"Mode d'action et efficacité\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"Délai de la prochaine injection et conduite à tenir en cas de retard\"\n        },\n        {\n         \"letter\": \"C\",\n         \"text\": \"Effets secondaires possibles, notamment les changements de saignement\"\n        },\n        {\n         \"letter\": \"D\",\n         \"text\": \"Aucune information si elle a déjà choisi\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": true,\n       \"answer\": \"A. Mode d'action et efficacité ; B. Délai de la prochaine injection et conduite à tenir en cas de retard ; C. Effets secondaires possibles, notamment les changements de saignement\",\n       \"answerLetters\": [\n        \"A\",\n        \"B\",\n        \"C\"\n       ],\n       \"explanation\": \"Avant l'injection, on explique le mode d'action et l'efficacité, la date exacte de la prochaine injection (notée sur la carte de rendez-vous) et la conduite en cas de retard, ainsi que les effets secondaires possibles (troubles des saignements, aménorrhée) qui ne sont pas graves. Même si la cliente a déjà choisi, l'information reste obligatoire (étape « Explications » du BERCER).\\n\\nSource : Cours SR/PF 2023 L2 INFAS, chap. 13 CHP, instructions aux utilisatrices de CIP, p. 83 ; chap. 6 Counseling (BERCER), p. 23\",\n       \"sourceDoc\": \"Prépa D.E — J2 SSR/PF MAN SF3 (corrigé expliqué)\",\n       \"sourceFile\": \"J2_SSR_PF_MAN_SF3_J2_corrige_explique.pdf\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-ssrpf-j2-sf3__13\",\n       \"num\": \"14\",\n       \"type\": \"CAS_CLINIQUE\",\n       \"typeLabel\": \"Étude de cas / Cas clinique\",\n       \"partieTitle\": \"Cas clinique\",\n       \"caseTitle\": \"Cas clinique\",\n       \"caseData\": \"Vous recevez Mme BOA Irène, âgée de 19 ans, GII PII, quatre semaines après son accouchement. Elle allaite son bébé et souhaite débuter une contraception injectable. Après un counseling, elle exprime une préférence pour le Depo-Provera. Vous devez vérifier son éligibilité, lui donner une information adaptée et assurer une prise en charge respectueuse de son choix.\",\n       \"text\": \"Quel effet secondaire peut être observé avec un injectable progestatif ?\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"Augmentation certaine de la fertilité pendant l'utilisation\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"Modifications des saignements menstruels\"\n        },\n        {\n         \"letter\": \"C\",\n         \"text\": \"Stérilité définitive systématique\"\n        },\n        {\n         \"letter\": \"D\",\n         \"text\": \"Protection garantie contre les IST\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": false,\n       \"answer\": \"B. Modifications des saignements menstruels\",\n       \"answerLetters\": [\n        \"B\"\n       ],\n       \"explanation\": \"Les troubles du cycle (spotting, aménorrhée, saignements irréguliers) sont les effets secondaires les plus fréquents des progestatifs, en particulier du Depo-Provera. Ils ne protègent pas contre les IST et ne rendent pas stérile : le retour de la fécondité est seulement retardé.\\n\\nSource : Cours SR/PF 2023 L2 INFAS, chap. 13 CHP, limites, p. 72 ; Cours SR L2 2023, exercices (« Les troubles du cycle menstruel sont les effets secondaires les plus fréquents du DEPO-PROVERA »)\",\n       \"sourceDoc\": \"Prépa D.E — J2 SSR/PF MAN SF3 (corrigé expliqué)\",\n       \"sourceFile\": \"J2_SSR_PF_MAN_SF3_J2_corrige_explique.pdf\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-ssrpf-j2-sf3__14\",\n       \"num\": \"15\",\n       \"type\": \"CAS_CLINIQUE\",\n       \"typeLabel\": \"Étude de cas / Cas clinique\",\n       \"partieTitle\": \"Cas clinique\",\n       \"caseTitle\": \"Cas clinique\",\n       \"caseData\": \"Vous recevez Mme BOA Irène, âgée de 19 ans, GII PII, quatre semaines après son accouchement. Elle allaite son bébé et souhaite débuter une contraception injectable. Après un counseling, elle exprime une préférence pour le Depo-Provera. Vous devez vérifier son éligibilité, lui donner une information adaptée et assurer une prise en charge respectueuse de son choix.\",\n       \"text\": \"Le Depo-Provera protège-t-il contre les IST/VIH ?\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"Oui, complètement\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"Oui, mais uniquement contre le VIH\"\n        },\n        {\n         \"letter\": \"C\",\n         \"text\": \"Oui, pendant trois mois\"\n        },\n        {\n         \"letter\": \"D\",\n         \"text\": \"Non, le préservatif reste indiqué pour la prévention des IST\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": false,\n       \"answer\": \"D. Non, le préservatif reste indiqué pour la prévention des IST\",\n       \"answerLetters\": [\n        \"D\"\n       ],\n       \"explanation\": \"Le Depo-Provera ne protège pas contre les IST/VIH. Parmi toutes les méthodes contraceptives, seuls les préservatifs protègent des IST, y compris le VIH et le VHB.\\n\\nSource : Cours SR/PF 2023 L2 INFAS, chap. 3 Généralités sur la contraception, p. 13 ; chap. 13 CHP, limites, p. 72\",\n       \"sourceDoc\": \"Prépa D.E — J2 SSR/PF MAN SF3 (corrigé expliqué)\",\n       \"sourceFile\": \"J2_SSR_PF_MAN_SF3_J2_corrige_explique.pdf\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-ssrpf-j2-sf3__15\",\n       \"num\": \"16\",\n       \"type\": \"CAS_CLINIQUE\",\n       \"typeLabel\": \"Étude de cas / Cas clinique\",\n       \"partieTitle\": \"Cas clinique\",\n       \"caseTitle\": \"Cas clinique\",\n       \"caseData\": \"Vous recevez Mme BOA Irène, âgée de 19 ans, GII PII, quatre semaines après son accouchement. Elle allaite son bébé et souhaite débuter une contraception injectable. Après un counseling, elle exprime une préférence pour le Depo-Provera. Vous devez vérifier son éligibilité, lui donner une information adaptée et assurer une prise en charge respectueuse de son choix.\",\n       \"text\": \"Si Mme BOA souhaite aussi réduire le risque d'IST, quelle recommandation est pertinente ?\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"Utiliser un préservatif en complément de la méthode choisie\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"Éviter toute discussion sur les IST\"\n        },\n        {\n         \"letter\": \"C\",\n         \"text\": \"Remplacer le counseling par une injection\"\n        },\n        {\n         \"letter\": \"D\",\n         \"text\": \"Choisir obligatoirement un DIU\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": false,\n       \"answer\": \"A. Utiliser un préservatif en complément de la méthode choisie\",\n       \"answerLetters\": [\n        \"A\"\n       ],\n       \"explanation\": \"Le cours recommande d'utiliser des préservatifs en plus des injectables si l'un des partenaires est à risque : c'est la double protection, discutée lors du counseling.\\n\\nSource : Cours SR/PF 2023 L2 INFAS, chap. 13 CHP, instructions aux utilisatrices de CIP, p. 83 ; chap. 6 Counseling (REDI), p. 23-24\",\n       \"sourceDoc\": \"Prépa D.E — J2 SSR/PF MAN SF3 (corrigé expliqué)\",\n       \"sourceFile\": \"J2_SSR_PF_MAN_SF3_J2_corrige_explique.pdf\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-ssrpf-j2-sf3__16\",\n       \"num\": \"17\",\n       \"type\": \"CAS_CLINIQUE\",\n       \"typeLabel\": \"Étude de cas / Cas clinique\",\n       \"partieTitle\": \"Cas clinique\",\n       \"caseTitle\": \"Cas clinique\",\n       \"caseData\": \"Vous recevez Mme BOA Irène, âgée de 19 ans, GII PII, quatre semaines après son accouchement. Elle allaite son bébé et souhaite débuter une contraception injectable. Après un counseling, elle exprime une préférence pour le Depo-Provera. Vous devez vérifier son éligibilité, lui donner une information adaptée et assurer une prise en charge respectueuse de son choix.\",\n       \"text\": \"La MAMA est une option contraceptive si :\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"L'allaitement est mixte avec compléments réguliers et les règles sont revenues\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"Le bébé a plus d'un an\"\n        },\n        {\n         \"letter\": \"C\",\n         \"text\": \"Le bébé a moins de six mois, la mère est aménorrhéique et l'allaitement est exclusif ou quasi exclusif\"\n        },\n        {\n         \"letter\": \"D\",\n         \"text\": \"Les règles ont repris\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": false,\n       \"answer\": \"C. Le bébé a moins de six mois, la mère est aménorrhéique et l'allaitement est exclusif ou quasi exclusif\",\n       \"answerLetters\": [\n        \"C\"\n       ],\n       \"explanation\": \"La MAMA n'est efficace que si les 3 conditions sont réunies : bébé de moins de 6 mois, femme aménorrhéique et allaitement exclusif (pas d'apport complémentaire, tétées fréquentes).\\n\\nSource : Cours SR/PF 2023 L2 INFAS, chap. 10 MAMA, conditions d'efficacité, p. 38\",\n       \"sourceDoc\": \"Prépa D.E — J2 SSR/PF MAN SF3 (corrigé expliqué)\",\n       \"sourceFile\": \"J2_SSR_PF_MAN_SF3_J2_corrige_explique.pdf\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-ssrpf-j2-sf3__17\",\n       \"num\": \"18\",\n       \"type\": \"CAS_CLINIQUE\",\n       \"typeLabel\": \"Étude de cas / Cas clinique\",\n       \"partieTitle\": \"Cas clinique\",\n       \"caseTitle\": \"Cas clinique\",\n       \"caseData\": \"Vous recevez Mme BOA Irène, âgée de 19 ans, GII PII, quatre semaines après son accouchement. Elle allaite son bébé et souhaite débuter une contraception injectable. Après un counseling, elle exprime une préférence pour le Depo-Provera. Vous devez vérifier son éligibilité, lui donner une information adaptée et assurer une prise en charge respectueuse de son choix.\",\n       \"text\": \"Mme BOA peut-elle se fier à la MAMA si l'un des trois critères n'est plus rempli ?\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"Oui, si elle allaite au moins une fois par jour\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"Oui, sans réévaluation\"\n        },\n        {\n         \"letter\": \"C\",\n         \"text\": \"Oui, jusqu'au deuxième anniversaire du bébé\"\n        },\n        {\n         \"letter\": \"D\",\n         \"text\": \"Non, il faut proposer rapidement une autre méthode contraceptive\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": false,\n       \"answer\": \"D. Non, il faut proposer rapidement une autre méthode contraceptive\",\n       \"answerLetters\": [\n        \"D\"\n       ],\n       \"explanation\": \"Dès qu'une condition n'est plus remplie (retour des règles, apport alimentaire complémentaire ou espacement des tétées, bébé de 6 mois ou plus), la possibilité de grossesse augmente : il faut aider la cliente à choisir une autre méthode, tout en encourageant la poursuite de l'allaitement.\\n\\nSource : Cours SR/PF 2023 L2 INFAS, chap. 10 MAMA, critères d'éligibilité et suivi, p. 38-39\",\n       \"sourceDoc\": \"Prépa D.E — J2 SSR/PF MAN SF3 (corrigé expliqué)\",\n       \"sourceFile\": \"J2_SSR_PF_MAN_SF3_J2_corrige_explique.pdf\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-ssrpf-j2-sf3__18\",\n       \"num\": \"19\",\n       \"type\": \"CAS_CLINIQUE\",\n       \"typeLabel\": \"Étude de cas / Cas clinique\",\n       \"partieTitle\": \"Cas clinique\",\n       \"caseTitle\": \"Cas clinique\",\n       \"caseData\": \"Vous recevez Mme BOA Irène, âgée de 19 ans, GII PII, quatre semaines après son accouchement. Elle allaite son bébé et souhaite débuter une contraception injectable. Après un counseling, elle exprime une préférence pour le Depo-Provera. Vous devez vérifier son éligibilité, lui donner une information adaptée et assurer une prise en charge respectueuse de son choix.\",\n       \"text\": \"Quel élément témoigne d'un counseling respectueux des droits de la cliente ?\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"Refuser de répondre aux questions\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"Respecter sa confidentialité, ses questions et son choix éclairé\"\n        },\n        {\n         \"letter\": \"C\",\n         \"text\": \"Décider sans son accord\"\n        },\n        {\n         \"letter\": \"D\",\n         \"text\": \"Partager son dossier avec des personnes non concernées\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": false,\n       \"answer\": \"B. Respecter sa confidentialité, ses questions et son choix éclairé\",\n       \"answerLetters\": [\n        \"B\"\n       ],\n       \"explanation\": \"Les principes du counseling garantissent le droit au caractère privé et confidentiel, la liberté de s'exprimer, la liberté de choisir la méthode et le consentement éclairé. Refuser de répondre, décider à sa place ou divulguer son dossier les violent.\\n\\nSource : Cours SR/PF 2023 L2 INFAS, chap. 6 Counseling, principes de base, p. 21-22\",\n       \"sourceDoc\": \"Prépa D.E — J2 SSR/PF MAN SF3 (corrigé expliqué)\",\n       \"sourceFile\": \"J2_SSR_PF_MAN_SF3_J2_corrige_explique.pdf\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-ssrpf-j2-sf3__19\",\n       \"num\": \"20\",\n       \"type\": \"CAS_CLINIQUE\",\n       \"typeLabel\": \"Étude de cas / Cas clinique\",\n       \"partieTitle\": \"Cas clinique\",\n       \"caseTitle\": \"Cas clinique\",\n       \"caseData\": \"Vous recevez Mme BOA Irène, âgée de 19 ans, GII PII, quatre semaines après son accouchement. Elle allaite son bébé et souhaite débuter une contraception injectable. Après un counseling, elle exprime une préférence pour le Depo-Provera. Vous devez vérifier son éligibilité, lui donner une information adaptée et assurer une prise en charge respectueuse de son choix.\",\n       \"text\": \"[À l'issue de] la prestation, quelle action contribue à la continuité des soins ?\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"Ne pas donner de consignes de suivi\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"Ne rien documenter\"\n        },\n        {\n         \"letter\": \"C\",\n         \"text\": \"Noter la méthode et la date, expliquer le rendez-vous suivant et les signes nécessitant une consultation\"\n        },\n        {\n         \"letter\": \"D\",\n         \"text\": \"Lui demander de revenir uniquement si elle tombe enceinte\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": false,\n       \"answer\": \"C. Noter la méthode et la date, expliquer le rendez-vous suivant et les signes nécessitant une consultation\",\n       \"answerLetters\": [\n        \"C\"\n       ],\n       \"explanation\": \"La continuité des soins passe par l'étape « Rendez-vous / Référence » du BERCER : noter la méthode et la date sur la carte, indiquer la date exacte du prochain rendez-vous et expliquer les signes d'alarme qui doivent faire consulter.\\n\\nSource : Cours SR/PF 2023 L2 INFAS, chap. 6 Counseling (BERCER), p. 23 ; chap. 13 CHP, instructions CIP et signes d'alarme, p. 83\",\n       \"sourceDoc\": \"Prépa D.E — J2 SSR/PF MAN SF3 (corrigé expliqué)\",\n       \"sourceFile\": \"J2_SSR_PF_MAN_SF3_J2_corrige_explique.pdf\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-ssrpf-j2-sf3__20\",\n       \"num\": \"21\",\n       \"type\": \"QCM\",\n       \"typeLabel\": \"QCM\",\n       \"partieTitle\": null,\n       \"caseTitle\": null,\n       \"caseData\": null,\n       \"text\": \"Les méthodes contraceptives basées sur la connaissance de la fécondité comprennent :\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"Méthode du calendrier\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"Méthode de Billings\"\n        },\n        {\n         \"letter\": \"C\",\n         \"text\": \"Observation des signes de fertilité\"\n        },\n        {\n         \"letter\": \"D\",\n         \"text\": \"Implant sous-cutané\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": true,\n       \"answer\": \"A. Méthode du calendrier ; B. Méthode de Billings ; C. Observation des signes de fertilité\",\n       \"answerLetters\": [\n        \"A\",\n        \"B\",\n        \"C\"\n       ],\n       \"explanation\": \"Les méthodes d'auto-observation (connaissance de la fécondité) comprennent la méthode du calendrier (Ogino-Knaus), la température basale, la glaire cervicale (Billings), la méthode sympto-thermique et les jours fixes : elles reposent toutes sur l'observation des signes de fertilité. L'implant est une méthode hormonale.\\n\\nSource : Cours SR/PF 2023 L2 INFAS, chap. 3 Généralités (classification), p. 13 ; chap. 8 Méthodes d'auto-observation, p. 28-30\",\n       \"sourceDoc\": \"Prépa D.E — J2 SSR/PF MAN SF3 (corrigé expliqué)\",\n       \"sourceFile\": \"J2_SSR_PF_MAN_SF3_J2_corrige_explique.pdf\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-ssrpf-j2-sf3__21\",\n       \"num\": \"22\",\n       \"type\": \"QCM\",\n       \"typeLabel\": \"QCM\",\n       \"partieTitle\": null,\n       \"caseTitle\": null,\n       \"caseData\": null,\n       \"text\": \"Parmi les méthodes de barrière figurent :\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"Diaphragme\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"Préservatif masculin\"\n        },\n        {\n         \"letter\": \"C\",\n         \"text\": \"DIU au cuivre\"\n        },\n        {\n         \"letter\": \"D\",\n         \"text\": \"Préservatif féminin\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": true,\n       \"answer\": \"A. Diaphragme ; B. Préservatif masculin ; D. Préservatif féminin\",\n       \"answerLetters\": [\n        \"A\",\n        \"B\",\n        \"D\"\n       ],\n       \"explanation\": \"Les méthodes de barrière empêchent les spermatozoïdes d'atteindre le canal cervical : préservatifs masculin et féminin, cape cervicale et diaphragme (plus les spermicides, barrière chimique). Le DIU au cuivre agit dans la cavité utérine (il altère les spermatozoïdes et modifie l'endomètre).\\n\\nSource : Cours SR/PF 2023 L2 INFAS, chap. 11 Méthodes de barrière, p. 40 et 46 ; chap. 14 DIU, p. 86 Remarque : dans le tableau de classification du chap. 3 (p. 13), le DIU TCu 380A figure sous « méthode de barrière mécanique », alors que le chap. 11 ne le compte pas parmi les barrières.\",\n       \"sourceDoc\": \"Prépa D.E — J2 SSR/PF MAN SF3 (corrigé expliqué)\",\n       \"sourceFile\": \"J2_SSR_PF_MAN_SF3_J2_corrige_explique.pdf\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-ssrpf-j2-sf3__22\",\n       \"num\": \"23\",\n       \"type\": \"QCM\",\n       \"typeLabel\": \"QCM\",\n       \"partieTitle\": null,\n       \"caseTitle\": null,\n       \"caseData\": null,\n       \"text\": \"[À] propos du préservatif :\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"Il contribue à prévenir les IST/VIH\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"Il doit être utilisé correctement à chaque rapport\"\n        },\n        {\n         \"letter\": \"C\",\n         \"text\": \"Il contribue à prévenir la grossesse\"\n        },\n        {\n         \"letter\": \"D\",\n         \"text\": \"Il protège à 100 % contre toutes les IST dans toutes les circonstances\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": true,\n       \"answer\": \"A. Il contribue à prévenir les IST/VIH ; B. Il doit être utilisé correctement à chaque rapport ; C. Il contribue à prévenir la grossesse\",\n       \"answerLetters\": [\n        \"A\",\n        \"B\",\n        \"C\"\n       ],\n       \"explanation\": \"Le préservatif empêche le sperme d'atteindre les voies génitales (contraception) et empêche le passage des micro-organismes (IST, VIH, VHB). Son efficacité dépend d'une utilisation correcte à chaque rapport : il n'est pas efficace à 100 % (2 à 12 grossesses pour 100 femmes la première année en utilisation courante).\\n\\nSource : Cours SR/PF 2023 L2 INFAS, chap. 11 Méthodes de barrière (préservatif masculin), p. 40-41\",\n       \"sourceDoc\": \"Prépa D.E — J2 SSR/PF MAN SF3 (corrigé expliqué)\",\n       \"sourceFile\": \"J2_SSR_PF_MAN_SF3_J2_corrige_explique.pdf\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-ssrpf-j2-sf3__23\",\n       \"num\": \"24\",\n       \"type\": \"QCM\",\n       \"typeLabel\": \"QCM\",\n       \"partieTitle\": null,\n       \"caseTitle\": null,\n       \"caseData\": null,\n       \"text\": \"Après une rupture de préservatif lors d'un rapport non protégé, il faut envisager :\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"Une évaluation du risque d'exposition au VIH et des mesures indiquées selon le protocole\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"L'absence de toute action\"\n        },\n        {\n         \"letter\": \"C\",\n         \"text\": \"Une évaluation rapide du besoin de contraception d'urgence\"\n        },\n        {\n         \"letter\": \"D\",\n         \"text\": \"Un conseil sur la prévention des IST\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": true,\n       \"answer\": \"A. Une évaluation du risque d'exposition au VIH et des mesures indiquées selon le protocole ; C. Une évaluation rapide du besoin de contraception d'urgence ; D. Un conseil sur la prévention des IST\",\n       \"answerLetters\": [\n        \"A\",\n        \"C\",\n        \"D\"\n       ],\n       \"explanation\": \"En cas de rupture pendant ou après l'éjaculation, le cours prévoit une contraception d'urgence (pilule dans les 72 h ou DIU dans les 5 jours) et l'application du protocole de prise en charge des accidents d'exposition au sang (AES) dans les 48 h pour la prévention du VIH ; le conseil sur la prévention des IST en fait partie. Ne rien faire est une erreur.\\n\\nSource : Cours SR/PF 2023 L2 INFAS, chap. 11 Méthodes de barrière, CAT en cas de rupture du préservatif, p. 45\",\n       \"sourceDoc\": \"Prépa D.E — J2 SSR/PF MAN SF3 (corrigé expliqué)\",\n       \"sourceFile\": \"J2_SSR_PF_MAN_SF3_J2_corrige_explique.pdf\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-ssrpf-j2-sf3__24\",\n       \"num\": \"25\",\n       \"type\": \"QCM\",\n       \"typeLabel\": \"QCM\",\n       \"partieTitle\": null,\n       \"caseTitle\": null,\n       \"caseData\": null,\n       \"text\": \"Les contraceptifs hormonaux combinés :\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"Associent un œstrogène et un progestatif\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"Peuvent contribuer à régulariser les saignements chez certaines utilisatrices\"\n        },\n        {\n         \"letter\": \"C\",\n         \"text\": \"Peuvent inhiber l'ovulation\"\n        },\n        {\n         \"letter\": \"D\",\n         \"text\": \"Protègent contre toutes les IST\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": true,\n       \"answer\": \"A. Associent un œstrogène et un progestatif ; B. Peuvent contribuer à régulariser les saignements chez certaines utilisatrices ; C. Peuvent inhiber l'ovulation\",\n       \"answerLetters\": [\n        \"A\",\n        \"B\",\n        \"C\"\n       ],\n       \"explanation\": \"Les CHC associent un œstrogène et un progestatif. Ils bloquent l'ovulation par l'inhibition de la sécrétion de LH et de FSH et ont, parmi leurs avantages, la régularisation du cycle menstruel. Ils ne protègent pas contre les IST.\\n\\nSource : Cours SR/PF 2023 L2 INFAS, chap. 12 Contraceptifs hormonaux combinés (CHC), définition, mode d'action et avantages, p. 47-49\",\n       \"sourceDoc\": \"Prépa D.E — J2 SSR/PF MAN SF3 (corrigé expliqué)\",\n       \"sourceFile\": \"J2_SSR_PF_MAN_SF3_J2_corrige_explique.pdf\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-ssrpf-j2-sf3__25\",\n       \"num\": \"26\",\n       \"type\": \"QCM\",\n       \"typeLabel\": \"QCM\",\n       \"partieTitle\": null,\n       \"caseTitle\": null,\n       \"caseData\": null,\n       \"text\": \"Les contraceptifs hormonaux progestatifs comprennent :\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"Certains injectables\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"Le DIU au cuivre\"\n        },\n        {\n         \"letter\": \"C\",\n         \"text\": \"Les implants sous-cutanés\"\n        },\n        {\n         \"letter\": \"D\",\n         \"text\": \"Certaines pilules progestatives\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": true,\n       \"answer\": \"A. Certains injectables ; C. Les implants sous-cutanés ; D. Certaines pilules progestatives\",\n       \"answerLetters\": [\n        \"A\",\n        \"C\",\n        \"D\"\n       ],\n       \"explanation\": \"Les CHP diffusent uniquement un progestatif : pilules progestatives (COP), injectables progestatifs (Depo-Provera, Sayana Press, Noristérat) et implants sous-cutanés. Le DIU au cuivre ne contient pas d'hormone.\\n\\nSource : Cours SR/PF 2023 L2 INFAS, chap. 13 CHP, définitions, p. 68 ; chap. 14 DIU, p. 86\",\n       \"sourceDoc\": \"Prépa D.E — J2 SSR/PF MAN SF3 (corrigé expliqué)\",\n       \"sourceFile\": \"J2_SSR_PF_MAN_SF3_J2_corrige_explique.pdf\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-ssrpf-j2-sf3__26\",\n       \"num\": \"27\",\n       \"type\": \"QCM\",\n       \"typeLabel\": \"QCM\",\n       \"partieTitle\": null,\n       \"caseTitle\": null,\n       \"caseData\": null,\n       \"text\": \"[Au cours du] counseling sur les contraceptifs injectables, il convient d'aborder :\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"Les changements possibles des saignements\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"La possibilité d'un délai de retour de la fertilité après l'arrêt selon la méthode\"\n        },\n        {\n         \"letter\": \"C\",\n         \"text\": \"Le calendrier des injections\"\n        },\n        {\n         \"letter\": \"D\",\n         \"text\": \"La protection contre les IST comme effet de l'injection\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": true,\n       \"answer\": \"A. Les changements possibles des saignements ; B. La possibilité d'un délai de retour de la fertilité après l'arrêt selon la méthode ; C. Le calendrier des injections\",\n       \"answerLetters\": [\n        \"A\",\n        \"B\",\n        \"C\"\n       ],\n       \"explanation\": \"Le counseling sur les injectables aborde les troubles possibles des saignements (spotting, aménorrhée), le calendrier des injections (12 semaines pour Depo-Provera) et le retard temporaire du retour de la fécondité (4 à 7 mois au plus après la dernière injection). Les injectables ne protègent pas contre les IST.\\n\\nSource : Cours SR/PF 2023 L2 INFAS, chap. 13 CHP, instructions aux utilisatrices de CIP, p. 83\",\n       \"sourceDoc\": \"Prépa D.E — J2 SSR/PF MAN SF3 (corrigé expliqué)\",\n       \"sourceFile\": \"J2_SSR_PF_MAN_SF3_J2_corrige_explique.pdf\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-ssrpf-j2-sf3__27\",\n       \"num\": \"28\",\n       \"type\": \"QCM\",\n       \"typeLabel\": \"QCM\",\n       \"partieTitle\": null,\n       \"caseTitle\": null,\n       \"caseData\": null,\n       \"text\": \"Concernant les implants contraceptifs :\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"Ils sont placés sous la peau du bras selon la technique recommandée\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"Ils libèrent un progestatif\"\n        },\n        {\n         \"letter\": \"C\",\n         \"text\": \"Le retrait doit être accessible à la demande de l'utilisatrice\"\n        },\n        {\n         \"letter\": \"D\",\n         \"text\": \"Ils protègent contre les IST\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": true,\n       \"answer\": \"A. Ils sont placés sous la peau du bras selon la technique recommandée ; B. Ils libèrent un progestatif ; C. Le retrait doit être accessible à la demande de l'utilisatrice\",\n       \"answerLetters\": [\n        \"A\",\n        \"B\",\n        \"C\"\n       ],\n       \"explanation\": \"Les implants sont des capsules souples contenant un progestatif (lévonorgestrel ou étonogestrel), placées sous la peau à la face interne du bras, à 6-8 cm du pli du coude. La cliente revient voir un prestataire pour le retrait quand elle le souhaite. Ils ne protègent pas contre les IST/VIH.\\n\\nSource : Cours SR/PF 2023 L2 INFAS, chap. 13 CHP, implants (définition, tableau, instructions), p. 68, 70, 72 et 84\",\n       \"sourceDoc\": \"Prépa D.E — J2 SSR/PF MAN SF3 (corrigé expliqué)\",\n       \"sourceFile\": \"J2_SSR_PF_MAN_SF3_J2_corrige_explique.pdf\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-ssrpf-j2-sf3__28\",\n       \"num\": \"29\",\n       \"type\": \"QCM\",\n       \"typeLabel\": \"QCM\",\n       \"partieTitle\": null,\n       \"caseTitle\": null,\n       \"caseData\": null,\n       \"text\": \"Concernant le DIU au cuivre :\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"Il s'agit d'une méthode de longue durée d'action\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"Il peut modifier les saignements menstruels\"\n        },\n        {\n         \"letter\": \"C\",\n         \"text\": \"Il est placé dans la cavité utérine par un prestataire formé\"\n        },\n        {\n         \"letter\": \"D\",\n         \"text\": \"Il protège contre le VIH\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": true,\n       \"answer\": \"A. Il s'agit d'une méthode de longue durée d'action ; B. Il peut modifier les saignements menstruels ; C. Il est placé dans la cavité utérine par un prestataire formé\",\n       \"answerLetters\": [\n        \"A\",\n        \"B\",\n        \"C\"\n       ],\n       \"explanation\": \"Le DIU au cuivre (TCu 380A) a une durée d'action de 12 ans (longue durée). Il est inséré dans la cavité utérine par un personnel formé et peut entraîner des saignements et des crampes plus prononcés les premiers mois. Comme toutes les méthodes autres que le préservatif, il ne protège pas contre le VIH.\\n\\nSource : Cours SR/PF 2023 L2 INFAS, chap. 14 DIU, définition, types et limites, p. 85-87\",\n       \"sourceDoc\": \"Prépa D.E — J2 SSR/PF MAN SF3 (corrigé expliqué)\",\n       \"sourceFile\": \"J2_SSR_PF_MAN_SF3_J2_corrige_explique.pdf\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-ssrpf-j2-sf3__29\",\n       \"num\": \"30\",\n       \"type\": \"QCM\",\n       \"typeLabel\": \"QCM\",\n       \"partieTitle\": null,\n       \"caseTitle\": null,\n       \"caseData\": null,\n       \"text\": \"Avant la pose d'un DIU, le prestataire doit notamment :\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"Garantir l'absence totale d'effets secondaires\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"Expliquer les bénéfices, risques et signes d'alerte\"\n        },\n        {\n         \"letter\": \"C\",\n         \"text\": \"Obtenir le consentement éclairé\"\n        },\n        {\n         \"letter\": \"D\",\n         \"text\": \"Évaluer l'éligibilité médicale et les situations cliniques pertinentes\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": true,\n       \"answer\": \"B. Expliquer les bénéfices, risques et signes d'alerte ; C. Obtenir le consentement éclairé ; D. Évaluer l'éligibilité médicale et les situations cliniques pertinentes\",\n       \"answerLetters\": [\n        \"B\",\n        \"C\",\n        \"D\"\n       ],\n       \"explanation\": \"Avant la pose, le prestataire évalue l'éligibilité (critères médicaux, dépistage des infections génitales recommandé), informe des effets secondaires et des signes d'alerte, puis obtient le consentement éclairé. Aucune méthode ne garantit l'absence totale d'effets secondaires.\\n\\nSource : Cours SR/PF 2023 L2 INFAS, chap. 14 DIU, limites et critères, p. 87-88 ; chap. 15 DIUPP (confirmation du choix et évaluations), p. 101 Remarque : dans le sujet, l'énoncé commence par « 50. », un reste de numérotation sans effet sur la réponse.\",\n       \"sourceDoc\": \"Prépa D.E — J2 SSR/PF MAN SF3 (corrigé expliqué)\",\n       \"sourceFile\": \"J2_SSR_PF_MAN_SF3_J2_corrige_explique.pdf\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-ssrpf-j2-sf3__30\",\n       \"num\": \"31\",\n       \"type\": \"QCM\",\n       \"typeLabel\": \"QCM\",\n       \"partieTitle\": null,\n       \"caseTitle\": null,\n       \"caseData\": null,\n       \"text\": \"Le DIU du post-partum (DIUPP) :\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"Nécessite un prestataire formé et le respect des règles de prévention des infections\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"Peut être inséré immédiatement après l'expulsion du placenta dans les conditions prévues\"\n        },\n        {\n         \"letter\": \"C\",\n         \"text\": \"N'exige jamais d'information préalable\"\n        },\n        {\n         \"letter\": \"D\",\n         \"text\": \"Est indiqué en cas de septicémie puerpérale\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": true,\n       \"answer\": \"A. Nécessite un prestataire formé et le respect des règles de prévention des infections ; B. Peut être inséré immédiatement après l'expulsion du placenta dans les conditions prévues\",\n       \"answerLetters\": [\n        \"A\",\n        \"B\"\n       ],\n       \"explanation\": \"Le DIUPP peut être inséré en post-placentaire (dans les 10 minutes après l'expulsion du placenta), en per-césarienne ou dans les 48 h. La femme doit avoir été informée et son choix confirmé ; la pose exige un prestataire formé et les pratiques de prévention des infections. La septicémie puerpérale est une catégorie 4 : contre-indication.\\n\\nSource : Cours SR/PF 2023 L2 INFAS, chap. 15 DIU du post-partum (DIUPP), p. 101-102\",\n       \"sourceDoc\": \"Prépa D.E — J2 SSR/PF MAN SF3 (corrigé expliqué)\",\n       \"sourceFile\": \"J2_SSR_PF_MAN_SF3_J2_corrige_explique.pdf\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-ssrpf-j2-sf3__31\",\n       \"num\": \"32\",\n       \"type\": \"QCM\",\n       \"typeLabel\": \"QCM\",\n       \"partieTitle\": null,\n       \"caseTitle\": null,\n       \"caseData\": null,\n       \"text\": \"[La] contraception chirurgicale volontaire (CCV) :\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"Peut comprendre l'occlusion des trompes chez la femme\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"Est considérée comme une méthode définitive\"\n        },\n        {\n         \"letter\": \"C\",\n         \"text\": \"N'exige pas de consentement éclairé\"\n        },\n        {\n         \"letter\": \"D\",\n         \"text\": \"Peut comprendre la vasectomie chez l'homme\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": true,\n       \"answer\": \"A. Peut comprendre l'occlusion des trompes chez la femme ; B. Est considérée comme une méthode définitive ; D. Peut comprendre la vasectomie chez l'homme\",\n       \"answerLetters\": [\n        \"A\",\n        \"B\",\n        \"D\"\n       ],\n       \"explanation\": \"La CCV met fin de façon définitive et irréversible à la possibilité de reproduction : ligature (section ou occlusion) des trompes chez la femme, vasectomie chez l'homme. Elle est pratiquée sur présentation d'une fiche de consentement signée.\\n\\nSource : Cours SR/PF 2023 L2 INFAS, chap. 16 Contraception chirurgicale volontaire (CCV), p. 121\",\n       \"sourceDoc\": \"Prépa D.E — J2 SSR/PF MAN SF3 (corrigé expliqué)\",\n       \"sourceFile\": \"J2_SSR_PF_MAN_SF3_J2_corrige_explique.pdf\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-ssrpf-j2-sf3__32\",\n       \"num\": \"33\",\n       \"type\": \"QCM\",\n       \"typeLabel\": \"QCM\",\n       \"partieTitle\": null,\n       \"caseTitle\": null,\n       \"caseData\": null,\n       \"text\": \"Avant une CCV, les principes essentiels comprennent :\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"Décision prise par le prestataire à la place du client\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"Information complète et compréhensible\"\n        },\n        {\n         \"letter\": \"C\",\n         \"text\": \"Absence de pression ou de contrainte\"\n        },\n        {\n         \"letter\": \"D\",\n         \"text\": \"Consentement volontaire et éclairé\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": true,\n       \"answer\": \"B. Information complète et compréhensible ; C. Absence de pression ou de contrainte ; D. Consentement volontaire et éclairé\",\n       \"answerLetters\": [\n        \"B\",\n        \"C\",\n        \"D\"\n       ],\n       \"explanation\": \"Le principe du consentement écrit et volontaire exige une information claire (autres méthodes temporaires, intervention chirurgicale, résultats permanents, libre choix), une décision ferme prise sans se sentir forcé, et la possibilité de retirer son consentement avant l'intervention. Le prestataire ne décide jamais à la place du client.\\n\\nSource : Cours SR/PF 2023 L2 INFAS, chap. 16 CCV, principe du consentement écrit et volontaire, p. 122\",\n       \"sourceDoc\": \"Prépa D.E — J2 SSR/PF MAN SF3 (corrigé expliqué)\",\n       \"sourceFile\": \"J2_SSR_PF_MAN_SF3_J2_corrige_explique.pdf\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-ssrpf-j2-sf3__33\",\n       \"num\": \"34\",\n       \"type\": \"QCM\",\n       \"typeLabel\": \"QCM\",\n       \"partieTitle\": null,\n       \"caseTitle\": null,\n       \"caseData\": null,\n       \"text\": \"Les critères de recevabilité médicale de l'OMS :\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"Doivent être appliqués à la situation individuelle\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"Aident à déterminer si une méthode peut être utilisée dans une situation donnée\"\n        },\n        {\n         \"letter\": \"C\",\n         \"text\": \"Remplacent entièrement le jugement clinique et les préférences du client\"\n        },\n        {\n         \"letter\": \"D\",\n         \"text\": \"Comportent quatre catégories\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": true,\n       \"answer\": \"A. Doivent être appliqués à la situation individuelle ; B. Aident à déterminer si une méthode peut être utilisée dans une situation donnée ; D. Comportent quatre catégories\",\n       \"answerLetters\": [\n        \"A\",\n        \"B\",\n        \"D\"\n       ],\n       \"explanation\": \"Les critères de recevabilité médicale de l'OMS classent en 4 catégories les situations (caractéristiques individuelles ou pathologies) pour dire si une méthode peut être utilisée chez une cliente donnée. Ils s'appliquent « avec jugement clinique » et ne remplacent ni ce jugement ni le libre choix de la cliente.\\n\\nSource : Cours SR/PF 2023 L2 INFAS, chap. 4 Critères médicaux d'éligibilité, définition et classification, p. 16-17\",\n       \"sourceDoc\": \"Prépa D.E — J2 SSR/PF MAN SF3 (corrigé expliqué)\",\n       \"sourceFile\": \"J2_SSR_PF_MAN_SF3_J2_corrige_explique.pdf\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-ssrpf-j2-sf3__34\",\n       \"num\": \"35\",\n       \"type\": \"QCM\",\n       \"typeLabel\": \"QCM\",\n       \"partieTitle\": null,\n       \"caseTitle\": null,\n       \"caseData\": null,\n       \"text\": \"Les qualités d'un bon conseiller comprennent :\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"Écoute active\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"Jugement moral du client\"\n        },\n        {\n         \"letter\": \"C\",\n         \"text\": \"Respect de la confidentialité\"\n        },\n        {\n         \"letter\": \"D\",\n         \"text\": \"Langage clair et adapté\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": true,\n       \"answer\": \"A. Écoute active ; C. Respect de la confidentialité ; D. Langage clair et adapté\",\n       \"answerLetters\": [\n        \"A\",\n        \"C\",\n        \"D\"\n       ],\n       \"explanation\": \"Parmi les qualités d'un bon conseiller : écouter activement, présenter l'information sans parti-pris avec une approche sans jugement, comprendre et respecter les droits du client (dont la confidentialité), comprendre l'effet de la communication et utiliser un langage adapté.\\n\\nSource : Cours SR/PF 2023 L2 INFAS, chap. 6 Counseling, qualités morales d'un bon conseiller, p. 22\",\n       \"sourceDoc\": \"Prépa D.E — J2 SSR/PF MAN SF3 (corrigé expliqué)\",\n       \"sourceFile\": \"J2_SSR_PF_MAN_SF3_J2_corrige_explique.pdf\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-ssrpf-j2-sf3__35\",\n       \"num\": \"36\",\n       \"type\": \"QCM\",\n       \"typeLabel\": \"QCM\",\n       \"partieTitle\": null,\n       \"caseTitle\": null,\n       \"caseData\": null,\n       \"text\": \"[Une] causerie éducative efficace repose notamment sur :\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"L'emploi obligatoire d'un vocabulaire technique complexe\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"Une préparation adaptée au thème et au public\"\n        },\n        {\n         \"letter\": \"C\",\n         \"text\": \"Un langage simple\"\n        },\n        {\n         \"letter\": \"D\",\n         \"text\": \"La possibilité pour les participants de poser des questions\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": true,\n       \"answer\": \"B. Une préparation adaptée au thème et au public ; C. Un langage simple ; D. La possibilité pour les participants de poser des questions\",\n       \"answerLetters\": [\n        \"B\",\n        \"C\",\n        \"D\"\n       ],\n       \"explanation\": \"Une causerie efficace se prépare (choix du sujet, du groupe cible, des messages et des supports adaptés), utilise un langage clair et simple et une méthode participative : on recueille les expériences, on dissipe les rumeurs et on laisse les participants poser des questions.\\n\\nSource : Cours SR/PF 2023 L2 INFAS, chap. 5 Causerie éducative, étapes et éléments d'une bonne causerie, p. 19-20\",\n       \"sourceDoc\": \"Prépa D.E — J2 SSR/PF MAN SF3 (corrigé expliqué)\",\n       \"sourceFile\": \"J2_SSR_PF_MAN_SF3_J2_corrige_explique.pdf\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-ssrpf-j2-sf3__36\",\n       \"num\": \"37\",\n       \"type\": \"QCM\",\n       \"typeLabel\": \"QCM\",\n       \"partieTitle\": null,\n       \"caseTitle\": null,\n       \"caseData\": null,\n       \"text\": \"La MAMA repose sur les critères suivants :\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"Aménorrhée\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"Enfant âgé de moins de six mois\"\n        },\n        {\n         \"letter\": \"C\",\n         \"text\": \"Retour des règles\"\n        },\n        {\n         \"letter\": \"D\",\n         \"text\": \"Allaitement exclusif ou quasi exclusif\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": true,\n       \"answer\": \"A. Aménorrhée ; B. Enfant âgé de moins de six mois ; D. Allaitement exclusif ou quasi exclusif\",\n       \"answerLetters\": [\n        \"A\",\n        \"B\",\n        \"D\"\n       ],\n       \"explanation\": \"Selon le cours, la MAMA repose sur 3 critères : aménorrhée, enfant de moins de 6 mois, allaitement exclusif ou quasi exclusif. Le retour des règles est au contraire un signe que la méthode n'est plus fiable.\\n\\nSource : Cours SR/PF 2023 L2 INFAS, chap. 10 MAMA, conditions d'efficacité, p. 38\",\n       \"sourceDoc\": \"Prépa D.E — J2 SSR/PF MAN SF3 (corrigé expliqué)\",\n       \"sourceFile\": \"J2_SSR_PF_MAN_SF3_J2_corrige_explique.pdf\",\n       \"sourcePage\": null,\n       \"off\": true\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-ssrpf-j2-sf3__37\",\n       \"num\": \"38\",\n       \"type\": \"QCM\",\n       \"typeLabel\": \"QCM\",\n       \"partieTitle\": null,\n       \"caseTitle\": null,\n       \"caseData\": null,\n       \"text\": \"Les éléments à aborder lors du choix contraceptif incluent :\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"Efficacité\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"Tolérance et préférences\"\n        },\n        {\n         \"letter\": \"C\",\n         \"text\": \"Sécurité et éligibilité médicale\"\n        },\n        {\n         \"letter\": \"D\",\n         \"text\": \"Coût, disponibilité et continuité d'utilisation selon le contexte\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": true,\n       \"answer\": \"A. Efficacité ; B. Tolérance et préférences ; C. Sécurité et éligibilité médicale ; D. Coût, disponibilité et continuité d'utilisation selon le contexte\",\n       \"answerLetters\": [\n        \"A\",\n        \"B\",\n        \"C\",\n        \"D\"\n       ],\n       \"explanation\": \"Le choix contraceptif tient compte des qualités d'une méthode : efficacité, sécurité, tolérance, coût, continuité d'utilisation (et réversibilité), ainsi que de l'éligibilité médicale et des préférences de la cliente.\\n\\nSource : Cours SR/PF 2023 L2 INFAS, chap. 3 Généralités, qualités d'une méthode contraceptive, p. 14\",\n       \"sourceDoc\": \"Prépa D.E — J2 SSR/PF MAN SF3 (corrigé expliqué)\",\n       \"sourceFile\": \"J2_SSR_PF_MAN_SF3_J2_corrige_explique.pdf\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-ssrpf-j2-sf3__38\",\n       \"num\": \"39\",\n       \"type\": \"QCM\",\n       \"typeLabel\": \"QCM\",\n       \"partieTitle\": null,\n       \"caseTitle\": null,\n       \"caseData\": null,\n       \"text\": \"En planification familiale, le suivi doit permettre :\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"De réévaluer la méthode si les besoins changent\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"D'évaluer la satisfaction et les éventuels effets secondaires\"\n        },\n        {\n         \"letter\": \"C\",\n         \"text\": \"D'interdire le changement de méthode\"\n        },\n        {\n         \"letter\": \"D\",\n         \"text\": \"De répondre aux questions de l'utilisatrice\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": true,\n       \"answer\": \"A. De réévaluer la méthode si les besoins changent ; B. D'évaluer la satisfaction et les éventuels effets secondaires ; D. De répondre aux questions de l'utilisatrice\",\n       \"answerLetters\": [\n        \"A\",\n        \"B\",\n        \"D\"\n       ],\n       \"explanation\": \"Lors du counseling de suivi, on discute de l'utilisation de la méthode, on vérifie si elle est satisfaisante et si des problèmes (effets secondaires) sont survenus, on répond aux questions et on aide à changer ou arrêter la méthode si besoin. Interdire le changement est contraire au libre choix.\\n\\nSource : Cours SR/PF 2023 L2 INFAS, chap. 6 Counseling, counseling de suivi et étape « Rendez-vous » du BERCER, p. 22-23\",\n       \"sourceDoc\": \"Prépa D.E — J2 SSR/PF MAN SF3 (corrigé expliqué)\",\n       \"sourceFile\": \"J2_SSR_PF_MAN_SF3_J2_corrige_explique.pdf\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-ssrpf-j2-sf3__39\",\n       \"num\": \"40\",\n       \"type\": \"QCM\",\n       \"typeLabel\": \"QCM\",\n       \"partieTitle\": null,\n       \"caseTitle\": null,\n       \"caseData\": null,\n       \"text\": \"Parmi les informations à donner à toute personne choisissant une méthode contraceptive, on retrouve :\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"Mode d'utilisation correct\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"Effets secondaires possibles et conduite à tenir\"\n        },\n        {\n         \"letter\": \"C\",\n         \"text\": \"Affirmation que la méthode ne présente aucun risque\"\n        },\n        {\n         \"letter\": \"D\",\n         \"text\": \"Signes d'alerte et recours aux soins si nécessaire\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": true,\n       \"answer\": \"A. Mode d'utilisation correct ; B. Effets secondaires possibles et conduite à tenir ; D. Signes d'alerte et recours aux soins si nécessaire\",\n       \"answerLetters\": [\n        \"A\",\n        \"B\",\n        \"D\"\n       ],\n       \"explanation\": \"L'étape « Explications » du BERCER comprend le mode d'utilisation de la méthode, les effets secondaires normaux et les signes d'alarme (avec le recours aux soins). Affirmer qu'une méthode est sans aucun risque est faux : la sécurité fait partie des qualités à évaluer.\\n\\nSource : Cours SR/PF 2023 L2 INFAS, chap. 6 Counseling (BERCER), p. 23 ; chap. 3 Généralités (sécurité), p. 14\",\n       \"sourceDoc\": \"Prépa D.E — J2 SSR/PF MAN SF3 (corrigé expliqué)\",\n       \"sourceFile\": \"J2_SSR_PF_MAN_SF3_J2_corrige_explique.pdf\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-ssrpf-j2-sf3__40\",\n       \"num\": \"41\",\n       \"type\": \"QCD\",\n       \"typeLabel\": \"QCD\",\n       \"partieTitle\": null,\n       \"caseTitle\": null,\n       \"caseData\": null,\n       \"text\": \"Les critères de recevabilité médicale de l'OMS classent les situations en quatre catégories.\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"Vrai\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"Faux\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": false,\n       \"answer\": \"A. Vrai\",\n       \"answerLetters\": [\n        \"A\"\n       ],\n       \"explanation\": \"Les critères de recevabilité médicale de l'OMS sont une classification en 4 catégories des états qui ont une incidence sur l'acceptabilité des méthodes contraceptives.\\n\\nSource : Cours SR/PF 2023 L2 INFAS, chap. 4 Critères médicaux d'éligibilité, p. 16\",\n       \"sourceDoc\": \"Prépa D.E — J2 SSR/PF MAN SF3 (corrigé expliqué)\",\n       \"sourceFile\": \"J2_SSR_PF_MAN_SF3_J2_corrige_explique.pdf\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-ssrpf-j2-sf3__41\",\n       \"num\": \"42\",\n       \"type\": \"QCD\",\n       \"typeLabel\": \"QCD\",\n       \"partieTitle\": null,\n       \"caseTitle\": null,\n       \"caseData\": null,\n       \"text\": \"La catégorie 1 signifie qu'il n'existe aucune restriction à l'utilisation de la méthode contraceptive.\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"Vrai\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"Faux\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": false,\n       \"answer\": \"A. Vrai\",\n       \"answerLetters\": [\n        \"A\"\n       ],\n       \"explanation\": \"Catégorie 1 = aucune restriction d'utilisation.\\n\\nSource : Cours SR/PF 2023 L2 INFAS, chap. 4 Critères médicaux d'éligibilité, p. 16\",\n       \"sourceDoc\": \"Prépa D.E — J2 SSR/PF MAN SF3 (corrigé expliqué)\",\n       \"sourceFile\": \"J2_SSR_PF_MAN_SF3_J2_corrige_explique.pdf\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-ssrpf-j2-sf3__42\",\n       \"num\": \"43\",\n       \"type\": \"QCD\",\n       \"typeLabel\": \"QCD\",\n       \"partieTitle\": null,\n       \"caseTitle\": null,\n       \"caseData\": null,\n       \"text\": \"La catégorie 4 signifie que les risques liés à l'utilisation de la méthode sont inacceptables pour la santé.\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"Vrai\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"Faux\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": false,\n       \"answer\": \"A. Vrai\",\n       \"answerLetters\": [\n        \"A\"\n       ],\n       \"explanation\": \"Catégorie 4 = risques inacceptables pour la santé : la méthode ne doit pas être utilisée.\\n\\nSource : Cours SR/PF 2023 L2 INFAS, chap. 4 Critères médicaux d'éligibilité, p. 16\",\n       \"sourceDoc\": \"Prépa D.E — J2 SSR/PF MAN SF3 (corrigé expliqué)\",\n       \"sourceFile\": \"J2_SSR_PF_MAN_SF3_J2_corrige_explique.pdf\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-ssrpf-j2-sf3__43\",\n       \"num\": \"44\",\n       \"type\": \"QCD\",\n       \"typeLabel\": \"QCD\",\n       \"partieTitle\": null,\n       \"caseTitle\": null,\n       \"caseData\": null,\n       \"text\": \"Le counseling vise à imposer au client la méthode jugée la plus adaptée par le prestataire\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"Vrai\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"Faux\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": false,\n       \"answer\": \"B. Faux\",\n       \"answerLetters\": [\n        \"B\"\n       ],\n       \"explanation\": \"Faux : le counseling aide le client à trouver et choisir lui-même la solution ; dans le BERCER, le prestataire aide à choisir la méthode qui répond aux besoins de la cliente mais ne choisit pas à sa place.\\n\\nSource : Cours SR/PF 2023 L2 INFAS, chap. 6 Counseling, définition et BERCER (« Ne pas choisir à sa place »), p. 21-23\",\n       \"sourceDoc\": \"Prépa D.E — J2 SSR/PF MAN SF3 (corrigé expliqué)\",\n       \"sourceFile\": \"J2_SSR_PF_MAN_SF3_J2_corrige_explique.pdf\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-ssrpf-j2-sf3__44\",\n       \"num\": \"45\",\n       \"type\": \"QCD\",\n       \"typeLabel\": \"QCD\",\n       \"partieTitle\": null,\n       \"caseTitle\": null,\n       \"caseData\": null,\n       \"text\": \"[Le counseling] doit favoriser une décision libre et éclairée de la personne.\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"Vrai\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"Faux\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": false,\n       \"answer\": \"A. Vrai\",\n       \"answerLetters\": [\n        \"A\"\n       ],\n       \"explanation\": \"Vrai : le counseling aide les clients à arriver à un choix éclairé, dans le respect de la liberté de choisir la méthode et du consentement éclairé.\\n\\nSource : Cours SR/PF 2023 L2 INFAS, chap. 6 Counseling, buts et principes, p. 21 Remarque : dans le sujet, l'énoncé commence par « doit favoriser… » ; il manque « Le counseling ».\",\n       \"sourceDoc\": \"Prépa D.E — J2 SSR/PF MAN SF3 (corrigé expliqué)\",\n       \"sourceFile\": \"J2_SSR_PF_MAN_SF3_J2_corrige_explique.pdf\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-ssrpf-j2-sf3__45\",\n       \"num\": \"46\",\n       \"type\": \"QCD\",\n       \"typeLabel\": \"QCD\",\n       \"partieTitle\": null,\n       \"caseTitle\": null,\n       \"caseData\": null,\n       \"text\": \"Le BERCER est un moyen mnémotechnique utilisé pour structurer les étapes du counseling en planification familiale.\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"Vrai\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"Faux\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": false,\n       \"answer\": \"A. Vrai\",\n       \"answerLetters\": [\n        \"A\"\n       ],\n       \"explanation\": \"Vrai : BERCER (Bienvenue, Entretien, Renseignements, Choix, Explications, Rendez-vous/Référence) est l'une des deux approches qui structurent les étapes du counseling, avec le REDI.\\n\\nSource : Cours SR/PF 2023 L2 INFAS, chap. 6 Counseling, étapes du BERCER, p. 23\",\n       \"sourceDoc\": \"Prépa D.E — J2 SSR/PF MAN SF3 (corrigé expliqué)\",\n       \"sourceFile\": \"J2_SSR_PF_MAN_SF3_J2_corrige_explique.pdf\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-ssrpf-j2-sf3__46\",\n       \"num\": \"47\",\n       \"type\": \"QCD\",\n       \"typeLabel\": \"QCD\",\n       \"partieTitle\": null,\n       \"caseTitle\": null,\n       \"caseData\": null,\n       \"text\": \"L'efficacité contraceptive correspond à la capacité d'une méthode à favoriser la survenue d'une grossesse.\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"Vrai\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"Faux\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": false,\n       \"answer\": \"B. Faux\",\n       \"answerLetters\": [\n        \"B\"\n       ],\n       \"explanation\": \"Faux : l'efficacité est la mesure dans laquelle une méthode est capable d'empêcher la survenue d'une grossesse, et non de la favoriser.\\n\\nSource : Cours SR/PF 2023 L2 INFAS, chap. 3 Généralités, qualités d'une méthode, p. 14\",\n       \"sourceDoc\": \"Prépa D.E — J2 SSR/PF MAN SF3 (corrigé expliqué)\",\n       \"sourceFile\": \"J2_SSR_PF_MAN_SF3_J2_corrige_explique.pdf\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-ssrpf-j2-sf3__47\",\n       \"num\": \"48\",\n       \"type\": \"QCD\",\n       \"typeLabel\": \"QCD\",\n       \"partieTitle\": null,\n       \"caseTitle\": null,\n       \"caseData\": null,\n       \"text\": \"L'ovulation survient généralement environ 14 jours avant le début des prochaines règles.\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"Vrai\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"Faux\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": false,\n       \"answer\": \"A. Vrai\",\n       \"answerLetters\": [\n        \"A\"\n       ],\n       \"explanation\": \"Vrai : les méthodes d'auto-observation reposent sur le principe qu'il n'y a en principe qu'une ovulation par cycle, en général 14 jours avant les prochaines règles.\\n\\nSource : Cours SR/PF 2023 L2 INFAS, chap. 8 Méthodes d'auto-observation, principes de base, p. 28-29\",\n       \"sourceDoc\": \"Prépa D.E — J2 SSR/PF MAN SF3 (corrigé expliqué)\",\n       \"sourceFile\": \"J2_SSR_PF_MAN_SF3_J2_corrige_explique.pdf\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-ssrpf-j2-sf3__48\",\n       \"num\": \"49\",\n       \"type\": \"QCD\",\n       \"typeLabel\": \"QCD\",\n       \"partieTitle\": null,\n       \"caseTitle\": null,\n       \"caseData\": null,\n       \"text\": \"La méthode de Billings repose notamment sur l'observation des modifications de la glaire cervicale.\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"Vrai\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"Faux\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": false,\n       \"answer\": \"A. Vrai\",\n       \"answerLetters\": [\n        \"A\"\n       ],\n       \"explanation\": \"Vrai : la méthode de Billings repose sur l'auto-observation par la femme des changements cycliques de sa glaire cervicale ; la glaire abondante, transparente et filante marque la période fertile.\\n\\nSource : Cours SR/PF 2023 L2 INFAS, chap. 8 Méthodes d'auto-observation, méthode de la glaire cervicale (Billings), p. 30\",\n       \"sourceDoc\": \"Prépa D.E — J2 SSR/PF MAN SF3 (corrigé expliqué)\",\n       \"sourceFile\": \"J2_SSR_PF_MAN_SF3_J2_corrige_explique.pdf\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-ssrpf-j2-sf3__49\",\n       \"num\": \"50\",\n       \"type\": \"QCD\",\n       \"typeLabel\": \"QCD\",\n       \"partieTitle\": null,\n       \"caseTitle\": null,\n       \"caseData\": null,\n       \"text\": \"Le coït interrompu protège efficacement contre les IST et le VIH.\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"Vrai\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"Faux\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": false,\n       \"answer\": \"B. Faux\",\n       \"answerLetters\": [\n        \"B\"\n       ],\n       \"explanation\": \"Faux : le coït interrompu (méthode du retrait) n'offre aucune protection contre les IST, y compris le VIH et le VHB.\\n\\nSource : Cours SR/PF 2023 L2 INFAS, chap. 9 Coït interrompu, inconvénients, p. 36\",\n       \"sourceDoc\": \"Prépa D.E — J2 SSR/PF MAN SF3 (corrigé expliqué)\",\n       \"sourceFile\": \"J2_SSR_PF_MAN_SF3_J2_corrige_explique.pdf\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-ssrpf-j2-sf3__50\",\n       \"num\": \"51\",\n       \"type\": \"QCD\",\n       \"typeLabel\": \"QCD\",\n       \"partieTitle\": null,\n       \"caseTitle\": null,\n       \"caseData\": null,\n       \"text\": \"La MAMA peut être utilisée comme méthode contraceptive si les trois critères sont réunis : aménorrhée, allaitement exclusif ou quasi exclusif, et bébé âgé de moins de six mois.\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"Vrai\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"Faux\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": false,\n       \"answer\": \"A. Vrai\",\n       \"answerLetters\": [\n        \"A\"\n       ],\n       \"explanation\": \"Vrai : ce sont les 3 conditions d'efficacité de la MAMA (efficacité de 98 % si elles sont réunies).\\n\\nSource : Cours SR/PF 2023 L2 INFAS, chap. 10 MAMA, conditions d'efficacité, p. 38\",\n       \"sourceDoc\": \"Prépa D.E — J2 SSR/PF MAN SF3 (corrigé expliqué)\",\n       \"sourceFile\": \"J2_SSR_PF_MAN_SF3_J2_corrige_explique.pdf\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-ssrpf-j2-sf3__51\",\n       \"num\": \"52\",\n       \"type\": \"QCD\",\n       \"typeLabel\": \"QCD\",\n       \"partieTitle\": null,\n       \"caseTitle\": null,\n       \"caseData\": null,\n       \"text\": \"La MAMA reste efficace jusqu'à deux ans après l'accouchement si l'allaitement se poursuit.\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"Vrai\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"Faux\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": false,\n       \"answer\": \"B. Faux\",\n       \"answerLetters\": [\n        \"B\"\n       ],\n       \"explanation\": \"Faux : la MAMA n'est utilisable que pendant les six premiers mois du post-partum (et avant le retour des règles). Au-delà, il faut une autre méthode, même si l'allaitement continue.\\n\\nSource : Cours SR/PF 2023 L2 INFAS, chap. 10 MAMA, définition et limites, p. 37-38\",\n       \"sourceDoc\": \"Prépa D.E — J2 SSR/PF MAN SF3 (corrigé expliqué)\",\n       \"sourceFile\": \"J2_SSR_PF_MAN_SF3_J2_corrige_explique.pdf\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-ssrpf-j2-sf3__52\",\n       \"num\": \"53\",\n       \"type\": \"QCD\",\n       \"typeLabel\": \"QCD\",\n       \"partieTitle\": null,\n       \"caseTitle\": null,\n       \"caseData\": null,\n       \"text\": \"Le préservatif masculin ou féminin contribue à la prévention des IST, notamment du VIH, en plus de prévenir une grossesse.\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"Vrai\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"Faux\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": false,\n       \"answer\": \"A. Vrai\",\n       \"answerLetters\": [\n        \"A\"\n       ],\n       \"explanation\": \"Vrai : le préservatif recueille le sperme (contraception) et empêche le passage des micro-organismes d'un partenaire à l'autre ; seuls les préservatifs protègent des IST, y compris le VIH et le VHB.\\n\\nSource : Cours SR/PF 2023 L2 INFAS, chap. 3 Généralités, p. 13 ; chap. 11 Méthodes de barrière, p. 40\",\n       \"sourceDoc\": \"Prépa D.E — J2 SSR/PF MAN SF3 (corrigé expliqué)\",\n       \"sourceFile\": \"J2_SSR_PF_MAN_SF3_J2_corrige_explique.pdf\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-ssrpf-j2-sf3__53\",\n       \"num\": \"54\",\n       \"type\": \"QCD\",\n       \"typeLabel\": \"QCD\",\n       \"partieTitle\": null,\n       \"caseTitle\": null,\n       \"caseData\": null,\n       \"text\": \"Les contraceptifs hormonaux combinés contiennent un œstrogène associé à un progestatif.\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"Vrai\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"Faux\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": false,\n       \"answer\": \"A. Vrai\",\n       \"answerLetters\": [\n        \"A\"\n       ],\n       \"explanation\": \"Vrai : les CHC désignent des produits contenant un œstrogène associé à un progestatif (pilules combinées, injectables combinés, patch, anneau).\\n\\nSource : Cours SR/PF 2023 L2 INFAS, chap. 12 CHC, définitions, p. 47\",\n       \"sourceDoc\": \"Prépa D.E — J2 SSR/PF MAN SF3 (corrigé expliqué)\",\n       \"sourceFile\": \"J2_SSR_PF_MAN_SF3_J2_corrige_explique.pdf\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-ssrpf-j2-sf3__54\",\n       \"num\": \"55\",\n       \"type\": \"QCD\",\n       \"typeLabel\": \"QCD\",\n       \"partieTitle\": null,\n       \"caseTitle\": null,\n       \"caseData\": null,\n       \"text\": \"Les contraceptifs hormonaux combinés favorisent l'ovulation en stimulant la sécrétion de LH et de FSH.\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"Vrai\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"Faux\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": false,\n       \"answer\": \"B. Faux\",\n       \"answerLetters\": [\n        \"B\"\n       ],\n       \"explanation\": \"Faux : les CHC bloquent l'ovulation par l'inhibition de la sécrétion de LH et de FSH ; ils ne la favorisent pas.\\n\\nSource : Cours SR/PF 2023 L2 INFAS, chap. 12 CHC, mode d'action, p. 49\",\n       \"sourceDoc\": \"Prépa D.E — J2 SSR/PF MAN SF3 (corrigé expliqué)\",\n       \"sourceFile\": \"J2_SSR_PF_MAN_SF3_J2_corrige_explique.pdf\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-ssrpf-j2-sf3__55\",\n       \"num\": \"56\",\n       \"type\": \"QCD\",\n       \"typeLabel\": \"QCD\",\n       \"partieTitle\": null,\n       \"caseTitle\": null,\n       \"caseData\": null,\n       \"text\": \"Les contraceptifs hormonaux progestatifs contiennent uniquement un progestatif.\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"Vrai\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"Faux\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": false,\n       \"answer\": \"A. Vrai\",\n       \"answerLetters\": [\n        \"A\"\n       ],\n       \"explanation\": \"Vrai : les CHP désignent des produits qui diffusent uniquement une hormone progestative (COP, injectables progestatifs, implants).\\n\\nSource : Cours SR/PF 2023 L2 INFAS, chap. 13 CHP, définitions, p. 68\",\n       \"sourceDoc\": \"Prépa D.E — J2 SSR/PF MAN SF3 (corrigé expliqué)\",\n       \"sourceFile\": \"J2_SSR_PF_MAN_SF3_J2_corrige_explique.pdf\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-ssrpf-j2-sf3__56\",\n       \"num\": \"57\",\n       \"type\": \"QCD\",\n       \"typeLabel\": \"QCD\",\n       \"partieTitle\": null,\n       \"caseTitle\": null,\n       \"caseData\": null,\n       \"text\": \"Le DIU au cuivre est une méthode contraceptive de longue durée d'action.\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"Vrai\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"Faux\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": false,\n       \"answer\": \"A. Vrai\",\n       \"answerLetters\": [\n        \"A\"\n       ],\n       \"explanation\": \"Vrai : le DIU au cuivre TCu 380A a une durée d'action de 12 ans ; le cours le classe en « longue durée d'action ».\\n\\nSource : Cours SR/PF 2023 L2 INFAS, chap. 14 DIU, types et avantages, p. 86-87\",\n       \"sourceDoc\": \"Prépa D.E — J2 SSR/PF MAN SF3 (corrigé expliqué)\",\n       \"sourceFile\": \"J2_SSR_PF_MAN_SF3_J2_corrige_explique.pdf\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-ssrpf-j2-sf3__57\",\n       \"num\": \"58\",\n       \"type\": \"QCD\",\n       \"typeLabel\": \"QCD\",\n       \"partieTitle\": null,\n       \"caseTitle\": null,\n       \"caseData\": null,\n       \"text\": \"Le DIU au cuivre protège contre les IST et le VIH.\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"Vrai\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"Faux\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": false,\n       \"answer\": \"B. Faux\",\n       \"answerLetters\": [\n        \"B\"\n       ],\n       \"explanation\": \"Faux : le DIU ne protège pas contre les IST/VIH ; il peut même aggraver les infections génitales hautes chez les femmes exposées. Seuls les préservatifs protègent des IST.\\n\\nSource : Cours SR/PF 2023 L2 INFAS, chap. 3 Généralités, p. 13 ; chap. 14 DIU, limites, p. 87\",\n       \"sourceDoc\": \"Prépa D.E — J2 SSR/PF MAN SF3 (corrigé expliqué)\",\n       \"sourceFile\": \"J2_SSR_PF_MAN_SF3_J2_corrige_explique.pdf\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-ssrpf-j2-sf3__58\",\n       \"num\": \"59\",\n       \"type\": \"QCD\",\n       \"typeLabel\": \"QCD\",\n       \"partieTitle\": null,\n       \"caseTitle\": null,\n       \"caseData\": null,\n       \"text\": \"La contraception chirurgicale volontaire est une méthode temporaire et facilement réversible\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"Vrai\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"Faux\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": false,\n       \"answer\": \"B. Faux\",\n       \"answerLetters\": [\n        \"B\"\n       ],\n       \"explanation\": \"Faux : la CCV met fin de façon définitive et irréversible à toute possibilité de reproduction.\\n\\nSource : Cours SR/PF 2023 L2 INFAS, chap. 16 CCV, définition, p. 121\",\n       \"sourceDoc\": \"Prépa D.E — J2 SSR/PF MAN SF3 (corrigé expliqué)\",\n       \"sourceFile\": \"J2_SSR_PF_MAN_SF3_J2_corrige_explique.pdf\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-ssrpf-j2-sf3__59\",\n       \"num\": \"60\",\n       \"type\": \"QCD\",\n       \"typeLabel\": \"QCD\",\n       \"partieTitle\": null,\n       \"caseTitle\": null,\n       \"caseData\": null,\n       \"text\": \"Avant une contraception chirurgicale volontaire, le consentement éclairé, volontaire et documenté de la personne est indispensable.\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"Vrai\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"Faux\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": false,\n       \"answer\": \"A. Vrai\",\n       \"answerLetters\": [\n        \"A\"\n       ],\n       \"explanation\": \"Vrai : la CCV est pratiquée sur présentation d'une fiche de consentement signée, après un counseling garantissant une décision libre et volontaire.\\n\\nSource : Cours SR/PF 2023 L2 INFAS, chap. 16 CCV, bénéficiaires et principe du consentement écrit et volontaire, p. 121-122\",\n       \"sourceDoc\": \"Prépa D.E — J2 SSR/PF MAN SF3 (corrigé expliqué)\",\n       \"sourceFile\": \"J2_SSR_PF_MAN_SF3_J2_corrige_explique.pdf\",\n       \"sourcePage\": null\n      }\n     ]\n    }\n   ]\n  }\n ]\n}";
